129		if os.Getenv("DRY_RUN") == "true" {
130			cfg.DryRun = true
131		}
132		if reconcileDryRun {
133			cfg.DryRun = true
134		}
135	
136		// Force from environment or flags.
137		if os.Getenv("FORCE") == "true" {
138			cfg.Force = true
139		}
140		if reconcileForce {
141			cfg.Force = true
142		}
143	
144		// State file from environment.
145		if stateDir := os.Getenv("BOSUN_STATE_DIR"); stateDir != "" {
146			cfg.StateFile = filepath.Join(stateDir, reconcile.DefaultStateFile)
147		}
148	
149		// Load post-sync hooks, settle delay, and deploy paths from project config file.
150		if projectCfg, err := config.Load(); err == nil {
151			cfg.PostSyncHooks.SetFromFile(projectCfg.PostSyncHooks())
152			cfg.HookSettleDelay.SetFromFile(projectCfg.HookSettleDelay())
153			cfg.DeployPaths.SetFromFile(projectCfg.DeployPaths())
154		}
155	
156		// Wire config reloader so the reconciler can re-read bosun.yaml from the repo.
157		cfg.ConfigReloader = func(dir string) (*reconcile.ReloadedConfig, error) {
158			projectCfg, err := config.LoadFrom(dir)
159			if err != nil {
160				return nil, err
161			}
162			hookSettleDelay := projectCfg.HookSettleDelay()
163			return &reconcile.ReloadedConfig{
164				PostSyncHooks:   projectCfg.PostSyncHooks(),
165				HookSettleDelay: &hookSettleDelay,
166				DeployPaths:     projectCfg.DeployPaths(),
167				DriftIgnore:     projectCfg.DriftIgnore(),
168			}, nil
169		}
170	
171		// Environment variable override for post-sync hooks (JSON, same as daemon).
172		if v := os.Getenv("BOSUN_POST_SYNC_HOOKS"); v != "" {
173			var hooks []reconcile.PostSyncHook
174			if err := json.Unmarshal([]byte(v), &hooks); err != nil {
175				log.Warn().Err(err).Msg("Failed to parse BOSUN_POST_SYNC_HOOKS, ignoring")
176			} else {
177				cfg.PostSyncHooks.SetFromEnv(hooks)
178			}
179		}
180	
181		// Environment variable override for hook settle delay.
182		if v := os.Getenv("BOSUN_HOOK_SETTLE_DELAY"); v != "" {
183			if d, err := time.ParseDuration(v); err == nil {
184				cfg.HookSettleDelay.SetFromEnv(d)
185			} else if d, err := time.ParseDuration(v + "s"); err == nil {
186				cfg.HookSettleDelay.SetFromEnv(d)
187			} else {
188				log.Warn().Str("value", v).Msg("Failed to parse BOSUN_HOOK_SETTLE_DELAY, ignoring")
189			}
190		}
191	
192		// Environment variable override for deploy paths (JSON array).
193		if v := os.Getenv("BOSUN_DEPLOY_PATHS"); v != "" {
194			var paths []string
195			if err := json.Unmarshal([]byte(v), &paths); err != nil {
196				log.Warn().Err(err).Msg("Failed to parse BOSUN_DEPLOY_PATHS, ignoring")
197			} else {
198				cfg.DeployPaths.SetFromEnv(paths)
199			}
200		}
201	
202		// Set source for state tracking.
203		cfg.Source = "cli"
204	
205		// Initialize OpenTelemetry tracing (noop if BOSUN_OTEL_ENDPOINT is unset).
206		initCtx := context.Background()
207		otelShutdown, otelErr := telemetry.Init(initCtx, "bosun", version, os.Getenv("BOSUN_OTEL_ENDPOINT"))
208		if otelErr != nil {
209			ui.Warning("Failed to initialize OpenTelemetry: %v", otelErr)
210		} else {
211			defer func() {
212				shutdownCtx, shutdownCancel := context.WithTimeout(context.Background(), 5*time.Second)
213				defer shutdownCancel()
214				_ = otelShutdown(shutdownCtx)
215			}()
216		}
217	
218		// Create context with cancellation on SIGINT/SIGTERM.
219		ctx, cancel := context.WithCancel(context.Background())
220		defer cancel()
221	
222		// Use sync.Once to ensure cancel() is only called once, preventing race condition
223		// when multiple signals arrive or when defer also calls cancel.
224		var cancelOnce sync.Once
225		safeCancel := func() {
226			cancelOnce.Do(func() {
227				ui.Warning("Received shutdown signal, cancelling...")
228				cancel()
229			})
230		}
231	
232		sigCh := make(chan os.Signal, 1)
233		signal.Notify(sigCh, syscall.SIGINT, syscall.SIGTERM)
234		go func() {
235			<-sigCh
236			safeCancel()
237		}()
238	
239		// Load targets and operational defaults from project config if available.
240		if projectCfg, err := config.Load(); err == nil {
241			if len(cfg.Targets) == 0 {
242				if targets := projectCfg.Targets(); len(targets) > 0 {
243					cfg.Targets = targets
244				}
245			}
246			// Hydrate base config with project-level operational defaults so
247			// ConfigForTarget can inherit them for named targets.
248			if len(cfg.CriticalContainers.Value) == 0 && !cfg.CriticalContainers.FromEnv() {
249				cfg.CriticalContainers.SetFromFile(projectCfg.CriticalContainers())
250			}
251			if len(cfg.DeploySyncPaths.Value) == 0 && !cfg.DeploySyncPaths.FromEnv() {
252				cfg.DeploySyncPaths.SetFromFile(projectCfg.DeploySyncPaths())
253			}
254			if len(cfg.DeploySyncExclude.Value) == 0 && !cfg.DeploySyncExclude.FromEnv() {
255				cfg.DeploySyncExclude.SetFromFile(projectCfg.DeploySyncExclude())
256			}
257		}
258	
259		// BOSUN_TARGETS env var overrides config file targets.
260		if v := os.Getenv("BOSUN_TARGETS"); v != "" {
261			var targets []reconcile.Target
262			if err := json.Unmarshal([]byte(v), &targets); err != nil {
263				log.Warn().Err(err).Msg("Failed to parse BOSUN_TARGETS, ignoring")
264			} else {
265				cfg.Targets = targets
266			}
267		}
268	
269		// Set up alert manager.
270		alerter := createAlertManager()
271	
272		opts := []reconcile.ReconcilerOption{}
273		if alerter != nil {
274			opts = append(opts, reconcile.WithAlerter(alerter))
275		}
276	
277		// Resolve targets and optionally filter by --target flag.
278		targets := cfg.ResolveTargets()
279		if reconcileTarget != "" {
280			var found bool
281			for _, t := range targets {
282				if t.Name == reconcileTarget {
283					targets = []reconcile.Target{t}
284					found = true
285					break
286				}
287			}
288			if !found {
289				ui.Fatal("Target %q not found in configuration", reconcileTarget)
290			}
291		}
292	
293		// Run reconciliation for each target.
294		var hadError bool
295		for _, target := range targets {
296			targetCfg := cfg.ConfigForTarget(target)
297			r := reconcile.NewReconciler(targetCfg, opts...)
298	
299			if !target.IsDefault() {
300				ui.Info("Reconciling target: %s", target.Name)
301			}
302	
303			if err := r.Run(ctx); err != nil {
304				ui.Error("Target %s failed: %v", target.Name, err)
305				hadError = true
306				continue
307			}
308		}
309	
310		if hadError {
311			ui.Fatal("Reconciliation completed with errors")
312		}
313	}
314	
315	// createAlertManager creates an alert manager with configured providers.
316	func createAlertManager() *alert.Manager {
317		mgr := alert.NewManager()
318	
319		// Add Discord provider.
320		discord := alert.NewDiscordProvider(os.Getenv("DISCORD_WEBHOOK_URL"))
321		mgr.AddProvider(discord)
322	
323		// Add Slack provider.
324		slack := alert.NewSlackProvider(os.Getenv("SLACK_WEBHOOK_URL"))
325		mgr.AddProvider(slack)
326	
327		// Add SendGrid provider.
328		toEmails := filterEmptyStrings(strings.Split(os.Getenv("SENDGRID_TO_EMAILS"), ","))
329		sendgrid := alert.NewSendGrid(alert.SendGridConfig{
330			APIKey:    os.Getenv("SENDGRID_API_KEY"),
331			FromEmail: os.Getenv("SENDGRID_FROM_EMAIL"),
332			FromName:  os.Getenv("SENDGRID_FROM_NAME"),
333			ToEmails:  toEmails,
334		})
335		mgr.AddProvider(sendgrid)
336	
337		// Add Twilio provider.
338		toNumbers := filterEmptyStrings(strings.Split(os.Getenv("TWILIO_TO_NUMBERS"), ","))
339		twilio := alert.NewTwilio(alert.TwilioConfig{
340			AccountSID: os.Getenv("TWILIO_ACCOUNT_SID"),
341			AuthToken:  os.Getenv("TWILIO_AUTH_TOKEN"),
342			FromNumber: os.Getenv("TWILIO_FROM_NUMBER"),
343			ToNumbers:  toNumbers,
344		})
345		mgr.AddProvider(twilio)
346	
347		// Add Webhook provider.
348		webhook := alert.NewWebhookProvider(alert.WebhookConfig{
349			URL:     os.Getenv("BOSUN_WEBHOOK_URL"),
350			Headers: parseJSONHeaders(os.Getenv("BOSUN_WEBHOOK_HEADERS")),
351			Method:  os.Getenv("BOSUN_WEBHOOK_METHOD"),
352		})
353		mgr.AddProvider(webhook)
354	
355		if !mgr.HasProviders() {
356			return nil
357		}
358	
359		ui.Info("Alert providers: %v", mgr.ProviderNames())
360		return mgr
361	}
362	
363	// filterEmptyStrings removes empty strings from a slice.
364	func filterEmptyStrings(ss []string) []string {
365		result := make([]string, 0, len(ss))
366		for _, s := range ss {
367			s = strings.TrimSpace(s)
368			if s != "" {
369				result = append(result, s)
370			}
371		}
372		return result
373	}
