1. Acquire lock (prevent concurrent runs)
2. Clone/pull repository
3. Decrypt secrets with SOPS
4. Render templates with Chezmoi
5. Create backup of current configs
6. Deploy (native file copy or tar-over-SSH for remote)
7. Docker compose up
8. SIGHUP to agentgateway
9. Release lock

Configuration is loaded from environment variables:
  REPO_URL        - Git repository URL (required)
  REPO_BRANCH     - Git branch to track (default: main)
  DEPLOY_TARGET   - Target host for remote deployment (e.g., root@192.168.1.8)
  SECRETS_FILES   - Comma-separated list of SOPS secret files relative to repo

Directories (defaults for container deployment):
  REPO_DIR        - Local repo directory (default: /app/repo)
  STAGING_DIR     - Staging directory (default: /app/staging)
  BACKUP_DIR      - Backup directory (default: /app/backups)
  LOG_DIR         - Log directory (default: /app/logs)
  LOCAL_APPDATA   - Local appdata path (default: /mnt/appdata)
  REMOTE_APPDATA  - Remote appdata path (default: /mnt/user/appdata)`,
	Run: runReconcile,
}

func init() {
	reconcileCmd.Flags().BoolVarP(&reconcileDryRun, "dry-run", "n", false, "Show what would be done without making changes")
	reconcileCmd.Flags().BoolVarP(&reconcileForce, "force", "f", false, "Force deployment even if no changes detected")
	reconcileCmd.Flags().BoolVarP(&reconcileLocal, "local", "l", false, "Force local deployment mode")
	reconcileCmd.Flags().StringVarP(&reconcileRemote, "remote", "r", "", "Target host for remote deployment (e.g., root@192.168.1.8)")
	reconcileCmd.Flags().StringVarP(&reconcileTarget, "target", "t", "", "Reconcile a single named target (from bosun.yaml targets: section)")

	rootCmd.AddCommand(reconcileCmd)
}

func runReconcile(cmd *cobra.Command, args []string) {
	// Build configuration from environment and flags.
	cfg := reconcile.DefaultConfig()

	// Required: repo URL.
	cfg.RepoURL = os.Getenv("REPO_URL")
	if cfg.RepoURL == "" {
		ui.Fatal("REPO_URL environment variable is required")
	}

	// Optional settings from environment.
	if branch := os.Getenv("REPO_BRANCH"); branch != "" {
		cfg.RepoBranch = branch
	}
	if repoDir := os.Getenv("REPO_DIR"); repoDir != "" {
		cfg.RepoDir = repoDir
	}
	if stagingDir := os.Getenv("STAGING_DIR"); stagingDir != "" {
		cfg.StagingDir = stagingDir
	}
	if backupDir := os.Getenv("BACKUP_DIR"); backupDir != "" {
		cfg.BackupDir = backupDir
	}
	if logDir := os.Getenv("LOG_DIR"); logDir != "" {
		cfg.LogDir = logDir
	}
	if localAppdata := os.Getenv("LOCAL_APPDATA"); localAppdata != "" {
		cfg.LocalAppdataPath = localAppdata
	}
	if remoteAppdata := os.Getenv("REMOTE_APPDATA"); remoteAppdata != "" {
		cfg.RemoteAppdataPath = remoteAppdata
	}

	// Secret files from environment.
	if secretsFiles := os.Getenv("SECRETS_FILES"); secretsFiles != "" {
		cfg.SecretsFiles = strings.Split(secretsFiles, ",")
		for i, f := range cfg.SecretsFiles {
			cfg.SecretsFiles[i] = strings.TrimSpace(f)
		}
	}

	// Target host from environment or flags.
	if target := os.Getenv("DEPLOY_TARGET"); target != "" {
		cfg.TargetHost = target
	}
	if reconcileRemote != "" {
		cfg.TargetHost = reconcileRemote
	}

	// Force local mode if --local flag is set.
	if reconcileLocal {
		cfg.DeployMode = "local"
	}

	// Dry run from environment or flags.
	if os.Getenv("DRY_RUN") == "true" {
		cfg.DryRun = true
	}
	if reconcileDryRun {
		cfg.DryRun = true
	}

	// Force from environment or flags.
	if os.Getenv("FORCE") == "true" {
		cfg.Force = true
	}
	if reconcileForce {
		cfg.Force = true
	}

	// State file from environment.
	if stateDir := os.Getenv("BOSUN_STATE_DIR"); stateDir != "" {
		cfg.StateFile = filepath.Join(stateDir, reconcile.DefaultStateFile)
	}

	// Load post-sync hooks, settle delay, and deploy paths from project config file.
	if projectCfg, err := config.Load(); err == nil {
		cfg.PostSyncHooks.SetFromFile(projectCfg.PostSyncHooks())
		cfg.HookSettleDelay.SetFromFile(projectCfg.HookSettleDelay())
		cfg.DeployPaths.SetFromFile(projectCfg.DeployPaths())
	}

	// Wire config reloader so the reconciler can re-read bosun.yaml from the repo.
	cfg.ConfigReloader = func(dir string) (*reconcile.ReloadedConfig, error) {
		projectCfg, err := config.LoadFrom(dir)
		if err != nil {
			return nil, err
		}
		hookSettleDelay := projectCfg.HookSettleDelay()
		return &reconcile.ReloadedConfig{
			PostSyncHooks:   projectCfg.PostSyncHooks(),
			HookSettleDelay: &hookSettleDelay,
			DeployPaths:     projectCfg.DeployPaths(),
			DriftIgnore:     projectCfg.DriftIgnore(),
		}, nil
	}

	// Environment variable override for post-sync hooks (JSON, same as daemon).
	if v := os.Getenv("BOSUN_POST_SYNC_HOOKS"); v != "" {
		var hooks []reconcile.PostSyncHook
		if err := json.Unmarshal([]byte(v), &hooks); err != nil {
			log.Warn().Err(err).Msg("Failed to parse BOSUN_POST_SYNC_HOOKS, ignoring")
		} else {
			cfg.PostSyncHooks.SetFromEnv(hooks)
		}
	}

	// Environment variable override for hook settle delay.
	if v := os.Getenv("BOSUN_HOOK_SETTLE_DELAY"); v != "" {
		if d, err := time.ParseDuration(v); err == nil {
			cfg.HookSettleDelay.SetFromEnv(d)
		} else if d, err := time.ParseDuration(v + "s"); err == nil {
			cfg.HookSettleDelay.SetFromEnv(d)
		} else {
			log.Warn().Str("value", v).Msg("Failed to parse BOSUN_HOOK_SETTLE_DELAY, ignoring")
		}
	}

	// Environment variable override for deploy paths (JSON array).
	if v := os.Getenv("BOSUN_DEPLOY_PATHS"); v != "" {
		var paths []string
		if err := json.Unmarshal([]byte(v), &paths); err != nil {
			log.Warn().Err(err).Msg("Failed to parse BOSUN_DEPLOY_PATHS, ignoring")
		} else {
			cfg.DeployPaths.SetFromEnv(paths)
		}
	}

	// Set source for state tracking.
	cfg.Source = "cli"

	// Initialize OpenTelemetry tracing (noop if BOSUN_OTEL_ENDPOINT is unset).
	initCtx := context.Background()
	otelShutdown, otelErr := telemetry.Init(initCtx, "bosun", version, os.Getenv("BOSUN_OTEL_ENDPOINT"))
	if otelErr != nil {
		ui.Warning("Failed to initialize OpenTelemetry: %v", otelErr)
	} else {
		defer func() {
			shutdownCtx, shutdownCancel := context.WithTimeout(context.Background(), 5*time.Second)
			defer shutdownCancel()
			_ = otelShutdown(shutdownCtx)
		}()
	}

	// Create context with cancellation on SIGINT/SIGTERM.
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	// Use sync.Once to ensure cancel() is only called once, preventing race condition
	// when multiple signals arrive or when defer also calls cancel.
	var cancelOnce sync.Once
	safeCancel := func() {
		cancelOnce.Do(func() {
			ui.Warning("Received shutdown signal, cancelling...")
			cancel()
		})
	}

	sigCh := make(chan os.Signal, 1)
	signal.Notify(sigCh, syscall.SIGINT, syscall.SIGTERM)
	go func() {
		<-sigCh
		safeCancel()
	}()

	// Load targets and operational defaults from project config if available.
	if projectCfg, err := config.Load(); err == nil {
		if len(cfg.Targets) == 0 {
			if targets := projectCfg.Targets(); len(targets) > 0 {
				cfg.Targets = targets
			}
		}
		// Hydrate base config with project-level operational defaults so
		// ConfigForTarget can inherit them for named targets.
		if len(cfg.CriticalContainers.Value) == 0 && !cfg.CriticalContainers.FromEnv() {
			cfg.CriticalContainers.SetFromFile(projectCfg.CriticalContainers())
		}
		if len(cfg.DeploySyncPaths.Value) == 0 && !cfg.DeploySyncPaths.FromEnv() {
			cfg.DeploySyncPaths.SetFromFile(projectCfg.DeploySyncPaths())
		}
		if len(cfg.DeploySyncExclude.Value) == 0 && !cfg.DeploySyncExclude.FromEnv() {
			cfg.DeploySyncExclude.SetFromFile(projectCfg.DeploySyncExclude())
		}
	}

	// BOSUN_TARGETS env var overrides config file targets.
	if v := os.Getenv("BOSUN_TARGETS"); v != "" {
		var targets []reconcile.Target
		if err := json.Unmarshal([]byte(v), &targets); err != nil {
			log.Warn().Err(err).Msg("Failed to parse BOSUN_TARGETS, ignoring")
		} else {
			cfg.Targets = targets
		}
	}

	// Set up alert manager.
	alerter := createAlertManager()

	opts := []reconcile.ReconcilerOption{}
	if alerter != nil {
		opts = append(opts, reconcile.WithAlerter(alerter))
	}

	// Resolve targets and optionally filter by --target flag.
	targets := cfg.ResolveTargets()
	if reconcileTarget != "" {
		var found bool
		for _, t := range targets {
			if t.Name == reconcileTarget {
				targets = []reconcile.Target{t}
				found = true
				break
			}
		}
		if !found {
			ui.Fatal("Target %q not found in configuration", reconcileTarget)
		}
	}

	// Run reconciliation for each target.
	var hadError bool
	for _, target := range targets {
		targetCfg := cfg.ConfigForTarget(target)
		r := reconcile.NewReconciler(targetCfg, opts...)

		if !target.IsDefault() {
			ui.Info("Reconciling target: %s", target.Name)
		}

		if err := r.Run(ctx); err != nil {
			ui.Error("Target %s failed: %v", target.Name, err)
			hadError = true
			continue
		}
	}

	if hadError {
		ui.Fatal("Reconciliation completed with errors")
	}
}

// createAlertManager creates an alert manager with configured providers.
func createAlertManager() *alert.Manager {
	mgr := alert.NewManager()

	// Add Discord provider.
	discord := alert.NewDiscordProvider(os.Getenv("DISCORD_WEBHOOK_URL"))
	mgr.AddProvider(discord)

	// Add Slack provider.
	slack := alert.NewSlackProvider(os.Getenv("SLACK_WEBHOOK_URL"))
	mgr.AddProvider(slack)

	// Add SendGrid provider.
	toEmails := filterEmptyStrings(strings.Split(os.Getenv("SENDGRID_TO_EMAILS"), ","))
	sendgrid := alert.NewSendGrid(alert.SendGridConfig{
		APIKey:    os.Getenv("SENDGRID_API_KEY"),
		FromEmail: os.Getenv("SENDGRID_FROM_EMAIL"),
		FromName:  os.Getenv("SENDGRID_FROM_NAME"),
		ToEmails:  toEmails,
	})
	mgr.AddProvider(sendgrid)

	// Add Twilio provider.
	toNumbers := filterEmptyStrings(strings.Split(os.Getenv("TWILIO_TO_NUMBERS"), ","))
	twilio := alert.NewTwilio(alert.TwilioConfig{
		AccountSID: os.Getenv("TWILIO_ACCOUNT_SID"),
		AuthToken:  os.Getenv("TWILIO_AUTH_TOKEN"),
		FromNumber: os.Getenv("TWILIO_FROM_NUMBER"),
		ToNumbers:  toNumbers,
	})
	mgr.AddProvider(twilio)

	// Add Webhook provider.
	webhook := alert.NewWebhookProvider(alert.WebhookConfig{
		URL:     os.Getenv("BOSUN_WEBHOOK_URL"),
		Headers: parseJSONHeaders(os.Getenv("BOSUN_WEBHOOK_HEADERS")),
		Method:  os.Getenv("BOSUN_WEBHOOK_METHOD"),
	})
	mgr.AddProvider(webhook)

	if !mgr.HasProviders() {
		return nil
	}

	ui.Info("Alert providers: %v", mgr.ProviderNames())
	return mgr
}

// filterEmptyStrings removes empty strings from a slice.
func filterEmptyStrings(ss []string) []string {
	result := make([]string, 0, len(ss))
	for _, s := range ss {
		s = strings.TrimSpace(s)
		if s != "" {
			result = append(result, s)
		}
	}
	return result
}

package daemon

import (
	"context"
	"crypto/hmac"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"strings"
	"sync"
	"time"

	"go.opentelemetry.io/otel/trace"

	"github.com/cameronsjo/bosun/internal/log"
	"github.com/cameronsjo/bosun/internal/telemetry"
	"github.com/cameronsjo/bosun/internal/ui"
	"github.com/prometheus/client_golang/prometheus"
	"github.com/prometheus/client_golang/prometheus/promhttp"
)

const (
	// maxWebhookBodySize is the maximum allowed size for webhook request bodies (1MB).
	// This prevents denial-of-service attacks via oversized payloads.
	maxWebhookBodySize = 1 * 1024 * 1024
)

// Server handles HTTP requests for webhooks and health checks.
type Server struct {
	daemon   *Daemon
	server   *http.Server
	registry *prometheus.Registry
	metrics  *Metrics

	// Track in-flight reconciliation goroutines for graceful shutdown
	wg sync.WaitGroup
}

// NewServer creates a new HTTP server for the daemon.
func NewServer(d *Daemon) *Server {
	reg := prometheus.NewRegistry()
	metrics := newMetrics(reg)

	s := &Server{
		daemon:   d,
		registry: reg,
		metrics:  metrics,
	}

	mux := http.NewServeMux()

	// Health endpoints
	mux.HandleFunc(d.config.HealthPath, s.handleHealth)
	mux.HandleFunc(d.config.ReadyPath, s.handleReady)

	// Webhook endpoints
	mux.HandleFunc(d.config.WebhookPath, s.handleWebhook)
	mux.HandleFunc(d.config.WebhookPath+"/github", s.handleGitHubWebhook)
	mux.HandleFunc(d.config.WebhookPath+"/manual", s.handleManualTrigger)

	// Widget endpoint for Homepage dashboard
	mux.HandleFunc("/api/widget", s.handleWidget)

	// Prometheus metrics endpoint
	mux.Handle("/metrics", s.metricsMiddleware(s.promHandler()))

	s.server = &http.Server{
		Handler:      s.loggingMiddleware(mux),
		ReadTimeout:  10 * time.Second,
		WriteTimeout: 30 * time.Second,
		IdleTimeout:  60 * time.Second,
	}

	return s
}

// Start starts the HTTP server on the given port.
func (s *Server) Start(port int) error {
	s.server.Addr = fmt.Sprintf(":%d", port)
	ui.Info("HTTP server listening on %s", s.server.Addr)
	return s.server.ListenAndServe()
}

// Shutdown gracefully shuts down the HTTP server.
// Waits for in-flight reconciliation goroutines to complete.
func (s *Server) Shutdown(ctx context.Context) error {
	// Stop accepting new connections
	err := s.server.Shutdown(ctx)

	// Wait for in-flight reconciliation goroutines
	done := make(chan struct{})
	go func() {
		s.wg.Wait()
		close(done)
	}()

	select {
	case <-done:
		// All goroutines completed
	case <-ctx.Done():
		log.Warn().Msg("Shutdown timeout waiting for in-flight reconciliations")
	}

	return err
}

// loggingMiddleware logs HTTP requests with request ID tracking.
func (s *Server) loggingMiddleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		start := time.Now()

		// Generate or extract request ID.
		requestID := r.Header.Get("X-Request-ID")
		if requestID == "" {
			var id string
			r = r.WithContext(log.WithRequestID(r.Context(), ""))
			id = log.RequestIDFromContext(r.Context())
			requestID = id
		} else {
			r = r.WithContext(log.WithRequestID(r.Context(), requestID))
		}

		// Stash enriched logger on context for downstream handlers.
		enriched := log.FromContext(r.Context())
		r = r.WithContext(log.WithContext(r.Context(), &enriched))

		// Add request ID to response headers.
		w.Header().Set("X-Request-ID", requestID)

		wrapped := &responseWriter{ResponseWriter: w, statusCode: http.StatusOK}
		next.ServeHTTP(wrapped, r)

		// Log with enriched logger that already carries request_id.
		enriched.Info().
			Str(log.FieldComponent, log.ComponentHTTP).
			Str(log.FieldMethod, r.Method).
			Str(log.FieldURL, r.URL.Path).
			Int(log.FieldStatus, wrapped.statusCode).
			Int64(log.FieldDurationMS, time.Since(start).Milliseconds()).
			Msg("HTTP request completed")
	})
}

type responseWriter struct {
	http.ResponseWriter
	statusCode int
}

func (rw *responseWriter) WriteHeader(code int) {
	rw.statusCode = code
	rw.ResponseWriter.WriteHeader(code)
}

// handleHealth handles the health check endpoint.
func (s *Server) handleHealth(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	status := s.daemon.HealthStatus()

	w.Header().Set("Content-Type", "application/json")
	if status.Status != "healthy" {
		w.WriteHeader(http.StatusServiceUnavailable)
	}

	_ = json.NewEncoder(w).Encode(status)
}

// handleReady handles the readiness check endpoint.
func (s *Server) handleReady(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	if !s.daemon.IsReady() {
		http.Error(w, "Not ready", http.StatusServiceUnavailable)
		return
	}

	w.WriteHeader(http.StatusOK)
	_, _ = w.Write([]byte("OK"))
}

// handleWebhook handles generic webhook requests.
func (s *Server) handleWebhook(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	// Validate webhook secret if configured
	if s.daemon.config.WebhookSecret != "" {
		sig := r.Header.Get("X-Signature")
		if sig == "" {
			sig = r.Header.Get("X-Hub-Signature-256")
		}

		// Limit body size to prevent DoS
		body, err := io.ReadAll(io.LimitReader(r.Body, maxWebhookBodySize))
		if err != nil {
			http.Error(w, "Failed to read body", http.StatusBadRequest)
			return
		}

		if !s.validateSignature(body, sig) {
			// Log security event for failed signature validation
			secLogger := log.ComponentCtx(r.Context(), log.ComponentHTTP)
			secLogger.Warn().
				Str("remote_addr", r.RemoteAddr).
				Str("endpoint", r.URL.Path).
				Msg("Webhook signature validation failed")
			http.Error(w, "Invalid signature", http.StatusUnauthorized)
			return
		}
	}

	// Propagate enriched logger into background context (request ctx is cancelled after response).
	bgCtx := log.WithContext(context.Background(), log.Ctx(r.Context()))

	s.metrics.RecordWebhookTrigger("generic")

	// Trigger reconciliation with goroutine tracking.
	webhookLogger := log.Component(log.ComponentWebhook)
	s.wg.Add(1)
	go func() {
		defer s.wg.Done()
		ctx, cancel := context.WithTimeout(bgCtx, s.daemon.config.ReconcileTimeout)
		defer cancel()
		ctx, webhookSpan := telemetry.Tracer("daemon").Start(ctx, "daemon.webhook",
			trace.WithAttributes(telemetry.StringAttr("webhook_type", "generic")),
		)
		err := s.daemon.TriggerReconcile(ctx, "webhook", false)
		if err != nil {
			telemetry.SpanError(webhookSpan, err)
			webhookLogger.Error().
				Err(err).
				Str(log.FieldSource, log.SourceWebhook).
				Msg("Webhook-triggered reconciliation failed")
		} else {
			telemetry.SpanOK(webhookSpan)
		}
		webhookSpan.End()
	}()

	w.WriteHeader(http.StatusAccepted)
	_ = json.NewEncoder(w).Encode(map[string]string{
		"status":  "accepted",
		"message": "Reconciliation triggered",
	})
}

// handleGitHubWebhook handles GitHub-specific webhook requests.
func (s *Server) handleGitHubWebhook(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	// Read body with size limit to prevent DoS
	body, err := io.ReadAll(io.LimitReader(r.Body, maxWebhookBodySize))
	if err != nil {
		http.Error(w, "Failed to read body", http.StatusBadRequest)
		return
	}

	// Validate GitHub signature
	if s.daemon.config.WebhookSecret != "" {
		sig := r.Header.Get("X-Hub-Signature-256")
		if !s.validateGitHubSignature(body, sig) {
			// Log security event for failed signature validation
			secLogger := log.ComponentCtx(r.Context(), log.ComponentHTTP)
			secLogger.Warn().
				Str("remote_addr", r.RemoteAddr).
				Str("endpoint", r.URL.Path).
				Str("event_type", r.Header.Get("X-GitHub-Event")).
				Msg("GitHub webhook signature validation failed")
			http.Error(w, "Invalid signature", http.StatusUnauthorized)
			return
		}
	}

	// Check event type
	eventType := r.Header.Get("X-GitHub-Event")
	action, reason := shouldProcessGitHubEvent(eventType)
	switch action {
	case "ping":
		w.WriteHeader(http.StatusOK)
		_, _ = w.Write([]byte("pong"))
		return
	case "ignore":
		w.WriteHeader(http.StatusOK)
		_ = json.NewEncoder(w).Encode(map[string]string{
			"status":  "ignored",
			"message": reason,
		})
		return
	}

	// Parse push event
	var payload GitHubPushPayload
	if err := json.Unmarshal(body, &payload); err != nil {
		http.Error(w, "Invalid JSON payload", http.StatusBadRequest)
		return
	}

	// Check if it's the branch we care about
	process, branchReason := shouldProcessGitHubPush(payload.Ref, s.daemon.config.ReconcileConfig.RepoBranch)
	if !process {
		w.WriteHeader(http.StatusOK)
		_ = json.NewEncoder(w).Encode(map[string]string{
			"status":  "ignored",
			"message": branchReason,
		})
		return
	}

	ghLogger := log.Component(log.ComponentWebhook)
	ghLogger.Info().
		Str(log.FieldSource, log.SourceGitHub).
		Str(log.FieldBranch, payload.Ref).
		Str("pusher", payload.Pusher.Name).
		Str(log.FieldCommit, payload.After).
		Msg("GitHub push received")

	s.metrics.RecordWebhookTrigger("github")

	// Propagate enriched logger into background context (request ctx is cancelled after response).
	bgCtx := log.WithContext(context.Background(), log.Ctx(r.Context()))

	// Trigger reconciliation with goroutine tracking
	s.wg.Add(1)
	go func() {
		defer s.wg.Done()
		ctx, cancel := context.WithTimeout(bgCtx, s.daemon.config.ReconcileTimeout)
		defer cancel()
		source := fmt.Sprintf("github:%s", payload.Pusher.Name)
		if err := s.daemon.TriggerReconcile(ctx, source, false); err != nil {
			ghLogger.Error().
				Err(err).
				Str(log.FieldSource, log.SourceGitHub).
				Msg("GitHub webhook reconciliation failed")
		}
	}()

	w.WriteHeader(http.StatusAccepted)
	_ = json.NewEncoder(w).Encode(map[string]string{
		"status":  "accepted",
		"message": "Reconciliation triggered",
		"commit":  payload.After,
	})
}

// handleManualTrigger handles manual reconciliation triggers.
func (s *Server) handleManualTrigger(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	// Validate signature if configured
	if s.daemon.config.WebhookSecret != "" {
		// Limit body size to prevent DoS
		body, err := io.ReadAll(io.LimitReader(r.Body, maxWebhookBodySize))
		if err != nil {
			http.Error(w, "Failed to read body", http.StatusBadRequest)
			return
		}

		sig := r.Header.Get("X-Signature")
		if !s.validateSignature(body, sig) {
			// Log security event for failed signature validation
			secLogger := log.ComponentCtx(r.Context(), log.ComponentHTTP)
			secLogger.Warn().
				Str("remote_addr", r.RemoteAddr).
				Str("endpoint", r.URL.Path).
				Msg("Manual trigger signature validation failed")
			http.Error(w, "Invalid signature", http.StatusUnauthorized)
			return
		}
	}

	// Propagate enriched logger into background context (request ctx is cancelled after response).
	bgCtx := log.WithContext(context.Background(), log.Ctx(r.Context()))

	s.metrics.RecordWebhookTrigger("manual")

	// Trigger reconciliation with goroutine tracking
	manualLogger := log.Component(log.ComponentWebhook)
	s.wg.Add(1)
	go func() {
		defer s.wg.Done()
		ctx, cancel := context.WithTimeout(bgCtx, s.daemon.config.ReconcileTimeout)
		defer cancel()
		if err := s.daemon.TriggerReconcile(ctx, "manual", false); err != nil {
			manualLogger.Error().
				Err(err).
				Str(log.FieldSource, log.SourceManual).
				Msg("Manual trigger reconciliation failed")
		}
	}()

	w.WriteHeader(http.StatusAccepted)
	_ = json.NewEncoder(w).Encode(map[string]string{
		"status":  "accepted",
		"message": "Manual reconciliation triggered",
	})
}

// handleWidget returns lightweight stats for Homepage's customapi widget.
func (s *Server) handleWidget(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	w.Header().Set("Content-Type", "application/json")
	_ = json.NewEncoder(w).Encode(s.daemon.WidgetData())
}

// promHandler returns the Prometheus HTTP handler for the server's registry.
func (s *Server) promHandler() http.Handler {
	return promhttp.HandlerFor(s.registry, promhttp.HandlerOpts{})
}

// metricsMiddleware refreshes point-in-time gauges (uptime, ready, last reconcile)
// before delegating to the Prometheus HTTP handler.
func (s *Server) metricsMiddleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodGet {
			http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
			return
		}

		status := s.daemon.HealthStatus()
		s.metrics.SetReady(status.Ready)
		s.metrics.SetUptime(status.Uptime.Seconds())

		if !status.LastReconcile.IsZero() {
			s.metrics.SetLastReconcileTime(float64(status.LastReconcile.Unix()))
		}

		next.ServeHTTP(w, r)
	})
}

// validateSignature validates a generic HMAC-SHA256 signature.
func (s *Server) validateSignature(body []byte, signature string) bool {
	if signature == "" {
		return false
	}

	// Remove "sha256=" prefix if present
	signature = strings.TrimPrefix(signature, "sha256=")

	expected := hmac.New(sha256.New, []byte(s.daemon.config.WebhookSecret))
	expected.Write(body)
	expectedSig := hex.EncodeToString(expected.Sum(nil))

	return hmac.Equal([]byte(signature), []byte(expectedSig))
}

// validateGitHubSignature validates a GitHub webhook signature.
func (s *Server) validateGitHubSignature(body []byte, signature string) bool {
	if signature == "" {
		return false
	}

	// GitHub uses "sha256=<hex>" format
	signature = strings.TrimPrefix(signature, "sha256=")

	mac := hmac.New(sha256.New, []byte(s.daemon.config.WebhookSecret))
	mac.Write(body)
	expectedMAC := hex.EncodeToString(mac.Sum(nil))

	return hmac.Equal([]byte(signature), []byte(expectedMAC))
}

// GitHubPushPayload represents a GitHub push webhook payload.
type GitHubPushPayload struct {
	Ref    string `json:"ref"`
	Before string `json:"before"`
	After  string `json:"after"`
	Pusher struct {
		Name  string `json:"name"`
		Email string `json:"email"`
	} `json:"pusher"`
	HeadCommit struct {
		ID      string `json:"id"`
		Message string `json:"message"`
		Author  struct {
			Name  string `json:"name"`
			Email string `json:"email"`
		} `json:"author"`
	} `json:"head_commit"`
	Repository struct {
		FullName string `json:"full_name"`
		CloneURL string `json:"clone_url"`
		SSHURL   string `json:"ssh_url"`
	} `json:"repository"`
}

// Package daemon provides a long-running daemon for GitOps operations.
package daemon

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net"
	"net/http"
	"os"
	"path/filepath"
	"time"

	"github.com/cameronsjo/bosun/internal/log"
	"github.com/cameronsjo/bosun/internal/ui"
)

// SocketServer handles Unix socket connections for the trigger API.
type SocketServer struct {
	daemon     *Daemon
	socketPath string
	listener   net.Listener
	httpServer *http.Server
}

// SocketConfig holds socket server configuration.
type SocketConfig struct {
	SocketPath string // Path to Unix socket (e.g., /var/run/bosun.sock)
	SocketMode os.FileMode // Socket file permissions (default: 0660)
}

// DefaultSocketConfig returns default socket configuration.
func DefaultSocketConfig() *SocketConfig {
	return &SocketConfig{
		SocketPath: DefaultSocketPath,
		SocketMode: 0660,
	}
}

// NewSocketServer creates a new Unix socket server.
func NewSocketServer(d *Daemon, cfg *SocketConfig) (*SocketServer, error) {
	if cfg == nil {
		cfg = DefaultSocketConfig()
	}

	s := &SocketServer{
		daemon:     d,
		socketPath: cfg.SocketPath,
	}

	// Create HTTP handler for socket
	mux := http.NewServeMux()
	mux.HandleFunc("/trigger", s.handleTrigger)
	mux.HandleFunc("/status", s.handleStatus)
	mux.HandleFunc("/health", s.handleHealth)
	mux.HandleFunc("/config", s.handleConfig)

	s.httpServer = &http.Server{
		Handler:      s.auditMiddleware(mux),
		ReadTimeout:  10 * time.Second,
		WriteTimeout: 30 * time.Second,
	}

	return s, nil
}

// Start starts the Unix socket server.
func (s *SocketServer) Start() error {
	// Ensure socket directory exists
	socketDir := filepath.Dir(s.socketPath)
	if err := os.MkdirAll(socketDir, 0755); err != nil {
		return fmt.Errorf("failed to create socket directory: %w", err)
	}

	// Remove stale socket if it exists
	if err := os.Remove(s.socketPath); err != nil && !os.IsNotExist(err) {
		return fmt.Errorf("failed to remove stale socket: %w", err)
	}

	// Create Unix socket listener
	listener, err := net.Listen("unix", s.socketPath)
	if err != nil {
		return fmt.Errorf("failed to create socket: %w", err)
	}
	s.listener = listener

	// Set socket permissions
	if err := os.Chmod(s.socketPath, 0660); err != nil {
		_ = listener.Close()
		return fmt.Errorf("failed to set socket permissions: %w", err)
